// Normalize leads from multiple sources into standard schema
const leads = [];

for (const item of $input.all()) {
  const data = item.json;
  leads.push({
    business_name: data.name || data.business_name || '',
    business_type: data.types ? data.types[0] : (data.categories ? data.categories[0].title : ''),
    location: data.formatted_address || `${data.location?.city}, ${data.location?.state}` || '',
    phone: data.formatted_phone_number || data.display_phone || '',
    website: data.website || data.url || '',
    rating: data.rating || 0,
    review_count: data.user_ratings_total || data.review_count || 0,
    source: data.place_id ? 'google_maps' : 'yelp',
    sourced_at: new Date().toISOString()
  });
}

return leads.map(l => ({ json: l }));

// Deduplication: check if lead already exists by name + location
// In production, this checks against your Google Sheet
const seen = new Set();
const unique = [];

for (const item of $input.all()) {
  const key = `${item.json.business_name.toLowerCase().trim()}|${item.json.location.toLowerCase().trim()}`;
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(item);
  }
}

return unique;

// Score each lead 0-100
for (const item of $input.all()) {
  const d = item.json;
  let score = 0;

  // Online presence (25 pts)
  if (d.website) score += 10;
  if (d.phone) score += 10;
  if (d.website && !d.website.includes('yelp.com')) score += 5;

  // Review activity (25 pts)
  if (d.review_count > 20) score += 15;
  if (d.rating >= 3.5) score += 10;

  // Business type fit (20 pts)
  const type = (d.business_type || '').toLowerCase();
  if (type.includes('cater')) score += 20;
  else if (type.includes('restaurant')) score += 15;
  else if (type.includes('food')) score += 10;
  else score += 5;

  // Location (15 pts) - placeholder, adjust radius logic
  if (d.location && d.location.toLowerCase().includes('champaign')) score += 15;
  else score += 8;

  // Growth signals (15 pts) - placeholder for enrichment data
  score += 0;

  item.json.lead_score = Math.min(score, 100);
  item.json.score_date = new Date().toISOString();
}

return $input.all();
